@namespace sv_77ca48c692d6437faa4b28fdbb1a43ee.Components.Pages.Settings
@using sv_77ca48c692d6437faa4b28fdbb1a43ee.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>
                    @if (_passwordMessage is not null)
                    {
                        <div class="toast @(_passwordSuccess ? "toast-success" : "toast-error")">@_passwordMessage</div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="status-row">
                <span class="status-indicator @(_twoFactorEnabled ? "status-on" : "status-off")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="text-muted">Last password change: @_lastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            @if (_sessions.Count == 0)
            {
                <p class="text-muted">No active sessions.</p>
            }
            else
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            <ActiveSessionRow
                                Session="session"
                                IsCurrent="@(session.Id == _sessions[0].Id)"
                                OnRevokeRequested="PromptRevoke" />
                        }
                    </tbody>
                </table>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                            @(_revoking ? "Revoking..." : "Revoke")
                        </button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@_revoking">Cancel</button>
                    </div>
                </div>
            </div>
        }

        @if (_errorMessage is not null)
        {
            <div class="toast toast-error">@_errorMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    // Password change state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordMessage;
    private bool _passwordSuccess;

    // Session revoke state
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetSecuritySettingsAsync();
            _twoFactorEnabled = settings.TwoFactorEnabled;
            _lastPasswordChange = settings.LastPasswordChange;
            _sessions = settings.Sessions;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task ChangePasswordAsync()
    {
        _passwordMessage = null;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordSuccess = false;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "Passwords do not match.";
            _passwordSuccess = false;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Failed: {ex.Message}";
            _passwordSuccess = false;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        _errorMessage = null;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to revoke session: {ex.Message}";
        }
        finally
        {
            _revoking = false;
        }
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }
}

